def run_mc(reps=160, seed=2026050202):
    rng = np.random.default_rng(seed)
    results = {d.key: {name: [] for name, _ in estimators} for d in dgps}
    failures = {d.key: {name: 0 for name, _ in estimators} for d in dgps}

